#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::Kelvin),
        TemperatureDelta::from_kelvins(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::Kelvin),
        TemperatureDelta::from_base(v).as_kelvins()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeCelsius),
        TemperatureDelta::from_degrees_celsius(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeCelsius),
        TemperatureDelta::from_base(v).as_degrees_celsius()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::MillidegreeCelsius),
        TemperatureDelta::from_millidegrees_celsius(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::MillidegreeCelsius),
        TemperatureDelta::from_base(v).as_millidegrees_celsius()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeDelisle),
        TemperatureDelta::from_degrees_delisle(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeDelisle),
        TemperatureDelta::from_base(v).as_degrees_delisle()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeFahrenheit),
        TemperatureDelta::from_degrees_fahrenheit(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeFahrenheit),
        TemperatureDelta::from_base(v).as_degrees_fahrenheit()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeNewton),
        TemperatureDelta::from_degrees_newton(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeNewton),
        TemperatureDelta::from_base(v).as_degrees_newton()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeRankine),
        TemperatureDelta::from_degrees_rankine(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeRankine),
        TemperatureDelta::from_base(v).as_degrees_rankine()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeReaumur),
        TemperatureDelta::from_degrees_reaumur(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeReaumur),
        TemperatureDelta::from_base(v).as_degrees_reaumur()
    );
    assert_eq!(
        TemperatureDelta::new(v, TemperatureDeltaUnit::DegreeRoemer),
        TemperatureDelta::from_degrees_roemer(v)
    );
    assert_eq!(
        TemperatureDelta::from_base(v).convert_to(TemperatureDeltaUnit::DegreeRoemer),
        TemperatureDelta::from_base(v).as_degrees_roemer()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [TemperatureDelta; 9] = [
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::Kelvin),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeCelsius),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::MillidegreeCelsius),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeDelisle),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeFahrenheit),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeNewton),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeRankine),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeReaumur),
        TemperatureDelta::const_new(1234.5, TemperatureDeltaUnit::DegreeRoemer),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(TemperatureDeltaUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            TemperatureDelta::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in TemperatureDeltaUnit::ALL {
            assert_eq!(
                TemperatureDelta::const_new(v, unit).as_base().to_bits(),
                TemperatureDelta::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = TemperatureDelta::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            TemperatureDelta::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in TemperatureDeltaUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        TemperatureDelta::from_base(0.0).auto_unit().unit,
        TemperatureDeltaUnit::Kelvin
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "∆K".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::Kelvin)
    );
    assert_eq!(
        format!("2.5 {}", "∆K").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(2.5, TemperatureDeltaUnit::Kelvin))
    );
    assert_eq!(
        "∆°C".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "∆°C").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeCelsius
        ))
    );
    assert_eq!(
        "m∆°C".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::MillidegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "m∆°C").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::MillidegreeCelsius
        ))
    );
    assert_eq!(
        "∆°De".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeDelisle)
    );
    assert_eq!(
        format!("2.5 {}", "∆°De").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeDelisle
        ))
    );
    assert_eq!(
        "∆°F".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeFahrenheit)
    );
    assert_eq!(
        format!("2.5 {}", "∆°F").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeFahrenheit
        ))
    );
    assert_eq!(
        "∆°N".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeNewton)
    );
    assert_eq!(
        format!("2.5 {}", "∆°N").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeNewton
        ))
    );
    assert_eq!(
        "∆°R".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeRankine)
    );
    assert_eq!(
        format!("2.5 {}", "∆°R").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeRankine
        ))
    );
    assert_eq!(
        "∆°Ré".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeReaumur)
    );
    assert_eq!(
        format!("2.5 {}", "∆°Ré").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeReaumur
        ))
    );
    assert_eq!(
        "∆°Rø".parse::<TemperatureDeltaUnit>(),
        Ok(TemperatureDeltaUnit::DegreeRoemer)
    );
    assert_eq!(
        format!("2.5 {}", "∆°Rø").parse::<TemperatureDelta>(),
        Ok(TemperatureDelta::new(
            2.5,
            TemperatureDeltaUnit::DegreeRoemer
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<TemperatureDelta>(),
        Err(ParseError::UnknownUnit)
    );
}

